/* Runtime for C code generated by sillyc, the self-hosted Silly Core compiler.
 *
 * Same memory model as the main runtime, simplified: one data stack per
 * process, reserved up front with mmap and never touched by malloc.  Strings
 * and list buffers are bump-allocated on it.  A string or list that ends at the
 * top of the stack grows in place, so appending in a loop costs O(n), not
 * O(n^2).  A function whose result holds no data-stack storage (and that has
 * no `&mut` parameter that could) resets the top to where it was on entry.
 */
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

typedef int64_t i64;
typedef struct { const uint8_t *p; i64 len; } sl_str;
typedef struct { void *ptr; i64 len, cap; } sl_list;   /* layout shared by every list type */

static uint8_t *ds_base, *ds_top, *ds_end;
static int sl_argc;
static char **sl_argv;

#define sl_lit(s, n) ((sl_str){(const uint8_t *)(s), (n)})

static void sl_panic(const char *where, const char *msg) {
    fflush(stdout);
    fprintf(stderr, "panic at %s: %s\n", where, msg);
    exit(101);
}

static void sl_init(int argc, char **argv) {
    size_t n = (size_t)8 << 30;
    const char *mb = getenv("SILLY_STACK_MB");
    if (mb && atol(mb) > 0) n = (size_t)atol(mb) << 20;
    ds_base = mmap(NULL, n, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
    if (ds_base == MAP_FAILED) { fprintf(stderr, "cannot reserve the data stack\n"); exit(101); }
    ds_top = ds_base;
    ds_end = ds_base + n;
    sl_argc = argc;
    sl_argv = argv;
}

static inline void sl_reserve(i64 n) {
    if (ds_end - ds_top < n) sl_panic("<runtime>", "data stack overflow");
}

static inline uint8_t *sl_bytes(i64 n) {
    sl_reserve(n);
    uint8_t *p = ds_top;
    ds_top += n;
    return p;
}

static inline void *sl_alloc(i64 n) {
    ds_top = (uint8_t *)(((uintptr_t)ds_top + 7) & ~(uintptr_t)7);
    return sl_bytes(n);
}

/* ---- integers ---- */

static inline i64 sl_div(i64 a, i64 b, const char *w) {
    if (b == 0) sl_panic(w, "division by zero");
    if (b == -1) return (i64)(0 - (uint64_t)a);
    return a / b;
}
static inline i64 sl_floordiv(i64 a, i64 b, const char *w) {
    i64 q = sl_div(a, b, w);
    if ((a % b != 0) && ((a < 0) != (b < 0))) q -= 1;
    return q;
}
static inline i64 sl_mod(i64 a, i64 b, const char *w) {
    if (b == 0) sl_panic(w, "division by zero");
    if (b == -1) return 0;
    i64 r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) r += b;
    return r;
}
static inline i64 sl_pow(i64 a, i64 b, const char *w) {
    if (b < 0) sl_panic(w, "negative exponent");
    uint64_t r = 1, x = (uint64_t)a;
    while (b) { if (b & 1) r *= x; x *= x; b >>= 1; }
    return (i64)r;
}
static void sl_oob(i64 i, i64 len, const char *w) {
    fflush(stdout);
    fprintf(stderr, "panic at %s: index %lld is out of range for length %lld\n", w, (long long)i, (long long)len);
    exit(101);
}
static inline i64 sl_index(i64 i, i64 len, const char *w) {
    if ((uint64_t)i < (uint64_t)len) return i;
    if (i < 0 && i + len >= 0) return i + len;
    sl_oob(i, len, w);
    return 0;
}

/* ---- strings ---- */

/* gcc cannot see that a literal `a` never ends at ds_top, and warns about the in-place growth. */
#pragma GCC diagnostic ignored "-Wstringop-overflow"
static inline sl_str sl_str_cat(sl_str a, sl_str b) {
    if (b.len == 0) return a;
    if (a.len == 0) return b;
    if (a.p + a.len == ds_top) {           /* a is the newest thing on the stack: grow it */
        memmove(sl_bytes(b.len), b.p, b.len);
        return (sl_str){a.p, a.len + b.len};
    }
    uint8_t *p = sl_bytes(a.len + b.len);
    memcpy(p, a.p, a.len);
    memcpy(p + a.len, b.p, b.len);
    return (sl_str){p, a.len + b.len};
}
static inline bool sl_str_eq(sl_str a, sl_str b) {
    return a.len == b.len && (a.len == 0 || memcmp(a.p, b.p, a.len) == 0);
}
static inline i64 sl_str_cmp(sl_str a, sl_str b) {
    i64 n = a.len < b.len ? a.len : b.len;
    int c = n ? memcmp(a.p, b.p, n) : 0;
    if (c) return c;
    return a.len < b.len ? -1 : a.len > b.len;
}
static inline uint8_t sl_str_at(sl_str s, i64 i, const char *w) {
    return s.p[sl_index(i, s.len, w)];
}
static inline sl_str sl_str_slice(sl_str s, i64 a, i64 b, bool has_b, const char *w) {
    if (!has_b) b = s.len;
    if (a < 0) a += s.len;
    if (b < 0) b += s.len;
    if (a < 0 || b > s.len || a > b) sl_panic(w, "slice out of bounds");
    return (sl_str){s.p + a, b - a};
}
static inline bool sl_str_starts(sl_str s, sl_str p) {
    return p.len <= s.len && (p.len == 0 || memcmp(s.p, p.p, p.len) == 0);
}
static inline bool sl_str_ends(sl_str s, sl_str p) {
    return p.len <= s.len && (p.len == 0 || memcmp(s.p + s.len - p.len, p.p, p.len) == 0);
}
static i64 sl_str_find(sl_str s, sl_str p) {
    for (i64 i = 0; i + p.len <= s.len; i++)
        if (memcmp(s.p + i, p.p, p.len) == 0) return i;
    return -1;
}
static sl_str sl_str_join(sl_str sep, const sl_str *xs, i64 n) {
    sl_str r = {(const uint8_t *)"", 0};
    for (i64 i = 0; i < n; i++) {
        if (i) r = sl_str_cat(r, sep);
        r = sl_str_cat(r, xs[i]);
    }
    return r;
}
static sl_str sl_int_str(i64 v) {
    char buf[24];
    int n = snprintf(buf, sizeof buf, "%lld", (long long)v);
    uint8_t *p = sl_bytes(n);
    memcpy(p, buf, n);
    return (sl_str){p, n};
}
static sl_str sl_char_str(uint32_t c) {
    uint8_t b[4];
    int n;
    if (c < 0x80) { b[0] = c; n = 1; }
    else if (c < 0x800) { b[0] = 0xC0 | (c >> 6); b[1] = 0x80 | (c & 63); n = 2; }
    else if (c < 0x10000) { b[0] = 0xE0 | (c >> 12); b[1] = 0x80 | ((c >> 6) & 63); b[2] = 0x80 | (c & 63); n = 3; }
    else { b[0] = 0xF0 | (c >> 18); b[1] = 0x80 | ((c >> 12) & 63); b[2] = 0x80 | ((c >> 6) & 63); b[3] = 0x80 | (c & 63); n = 4; }
    uint8_t *p = sl_bytes(n);
    memcpy(p, b, n);
    return (sl_str){p, n};
}
static inline sl_str sl_bool_str(bool b) { return b ? sl_lit("true", 4) : sl_lit("false", 5); }
static sl_str sl_cstr(const char *s) {
    i64 n = strlen(s);
    uint8_t *p = sl_bytes(n);
    memcpy(p, s, n);
    return (sl_str){p, n};
}
static char *sl_to_c(sl_str s) {               /* NUL-terminated copy, for libc */
    char *p = (char *)sl_bytes(s.len + 1);
    memcpy(p, s.p, s.len);
    p[s.len] = 0;
    return p;
}

/* ---- output ---- */

static inline void sl_wr(FILE *f, sl_str s) { fwrite(s.p, 1, s.len, f); }
static inline void sl_wr_int(FILE *f, i64 v) { fprintf(f, "%lld", (long long)v); }
static inline void sl_wr_char(FILE *f, uint32_t c) {
    uint8_t *mark = ds_top;
    sl_wr(f, sl_char_str(c));
    ds_top = mark;
}
static inline void sl_wr_bool(FILE *f, bool b) { sl_wr(f, sl_bool_str(b)); }

/* ---- lists ---- */

static void sl_grow(sl_list *l, i64 esz) {
    i64 cap = l->cap ? l->cap * 2 : 4;
    uint8_t *end = (uint8_t *)l->ptr + l->cap * esz;
    if (l->ptr && end == ds_top) {         /* the newest buffer on the stack: extend it */
        sl_bytes((cap - l->cap) * esz);
    } else {
        void *p = sl_alloc(cap * esz);
        if (l->len) memcpy(p, l->ptr, l->len * esz);
        l->ptr = p;
    }
    l->cap = cap;
}

static inline void sl_push_str(sl_list *l, sl_str s) {
    if (l->len == l->cap) sl_grow(l, sizeof(sl_str));
    ((sl_str *)l->ptr)[l->len++] = s;
}

/* ---- more strings (same behaviour as the main runtime) ---- */

static inline bool sl_isspace(uint8_t c) { return c == ' ' || (c >= '\t' && c <= '\r'); }
static sl_str sl_str_trim_start(sl_str s) {
    while (s.len && sl_isspace(s.p[0])) s.p++, s.len--;
    return s;
}
static sl_str sl_str_trim_end(sl_str s) {
    while (s.len && sl_isspace(s.p[s.len - 1])) s.len--;
    return s;
}
static sl_str sl_str_trim(sl_str s) { return sl_str_trim_end(sl_str_trim_start(s)); }
static sl_str sl_str_case(sl_str s, bool upper) {
    uint8_t *p = sl_bytes(s.len);
    for (i64 i = 0; i < s.len; i++) {
        uint8_t c = s.p[i];
        if (upper && c >= 'a' && c <= 'z') c -= 32;
        else if (!upper && c >= 'A' && c <= 'Z') c += 32;
        p[i] = c;
    }
    return (sl_str){p, s.len};
}
static i64 sl_str_find_from(sl_str s, sl_str p, i64 from) {
    for (i64 i = from; i + p.len <= s.len; i++)
        if (p.len == 0 || memcmp(s.p + i, p.p, p.len) == 0) return i;
    return -1;
}
static i64 sl_str_count(sl_str s, sl_str t) {
    if (t.len == 0) return s.len + 1;
    i64 c = 0, i = 0;
    while ((i = sl_str_find_from(s, t, i)) >= 0) c++, i += t.len;
    return c;
}
static sl_list sl_str_split(sl_str s, sl_str sep, bool ws) {
    sl_list out = {0};
    if (ws) {
        i64 i = 0;
        for (;;) {
            while (i < s.len && sl_isspace(s.p[i])) i++;
            if (i >= s.len) break;
            i64 j = i;
            while (j < s.len && !sl_isspace(s.p[j])) j++;
            sl_push_str(&out, (sl_str){s.p + i, j - i});
            i = j;
        }
        return out;
    }
    if (sep.len == 0) sl_panic("split", "empty separator");
    i64 i = 0;
    for (;;) {
        i64 j = sl_str_find_from(s, sep, i);
        i64 e = j < 0 ? s.len : j;
        sl_push_str(&out, (sl_str){s.p + i, e - i});
        if (j < 0) break;
        i = j + sep.len;
    }
    return out;
}
static sl_list sl_str_lines(sl_str s) {
    sl_list out = {0};
    i64 i = 0;
    while (i < s.len) {
        const uint8_t *nl = memchr(s.p + i, '\n', s.len - i);
        i64 e = nl ? nl - s.p : s.len;
        i64 ee = (e > i && s.p[e - 1] == '\r') ? e - 1 : e;
        sl_push_str(&out, (sl_str){s.p + i, ee - i});
        i = e + 1;
    }
    return out;
}
static sl_str sl_str_replace(sl_str s, sl_str a, sl_str b) {
    if (a.len == 0 || sl_str_find_from(s, a, 0) < 0) return s;
    sl_str r = {s.p, 0};
    i64 i = 0, j;
    uint8_t *p = sl_bytes(0);
    r.p = p;
    while ((j = sl_str_find_from(s, a, i)) >= 0) {
        memcpy(sl_bytes(j - i), s.p + i, j - i);
        memcpy(sl_bytes(b.len), b.p, b.len);
        i = j + a.len;
    }
    memcpy(sl_bytes(s.len - i), s.p + i, s.len - i);
    r.len = ds_top - p;
    return r;
}
static bool sl_parse_int(sl_str s, i64 *out) {
    s = sl_str_trim(s);
    i64 i = 0;
    bool neg = false;
    if (i < s.len && (s.p[i] == '-' || s.p[i] == '+')) neg = s.p[i++] == '-';
    if (i >= s.len) return false;
    uint64_t v = 0;
    for (; i < s.len; i++) {
        uint8_t c = s.p[i];
        if (c == '_' && i > 0) continue;
        if (c < '0' || c > '9') return false;
        if (v > (UINT64_MAX - 9) / 10) return false;
        v = v * 10 + (c - '0');
    }
    if (v > (uint64_t)INT64_MAX + neg) return false;
    *out = neg ? (i64)(0 - v) : (i64)v;
    return true;
}
static uint32_t sl_utf8_next(sl_str s, i64 *i) {
    uint8_t c = s.p[*i];
    if (c < 0x80) { (*i)++; return c; }
    int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : c >= 0xC0 ? 2 : 1;
    if (*i + len > s.len) len = 1;
    uint32_t cp = len == 1 ? 0xFFFD : len == 2 ? (c & 0x1F) : len == 3 ? (c & 0x0F) : (c & 0x07);
    for (int k = 1; k < len; k++) cp = (cp << 6) | (s.p[*i + k] & 0x3F);
    *i += len;
    return cp;
}
static uint32_t sl_chr(i64 x, const char *w) {
    if ((uint64_t)x > 0x10FFFF || (x >= 0xD800 && x <= 0xDFFF)) {
        fflush(stdout);
        fprintf(stderr, "panic at %s: %lld is not a valid char\n", w, (long long)x);
        exit(101);
    }
    return (uint32_t)x;
}
static sl_list sl_str_chars(sl_str s) {
    sl_list out = {0};
    for (i64 i = 0; i < s.len;) {
        uint32_t c = sl_utf8_next(s, &i);
        if (out.len == out.cap) sl_grow(&out, sizeof(uint32_t));
        ((uint32_t *)out.ptr)[out.len++] = c;
    }
    return out;
}
static sl_list sl_str_bytes(sl_str s) {
    sl_list out = {0};
    for (i64 i = 0; i < s.len; i++) {
        if (out.len == out.cap) sl_grow(&out, 1);
        ((uint8_t *)out.ptr)[out.len++] = s.p[i];
    }
    return out;
}
static void sl_panic_str(const char *where, sl_str msg) {
    fflush(stdout);
    fprintf(stderr, "panic at %s: %.*s\n", where, (int)msg.len, (const char *)msg.p);
    exit(101);
}
static sl_list sl_args(void) {
    sl_list out = {0};
    for (int i = 0; i < sl_argc; i++) sl_push_str(&out, (sl_str){(const uint8_t *)sl_argv[i], strlen(sl_argv[i])});
    return out;
}

/* ---- files and processes ---- */

static bool sl_read_file(sl_str path, sl_str *out, sl_str *err) {
    uint8_t *mark = ds_top;
    FILE *f = fopen(sl_to_c(path), "rb");
    ds_top = mark;
    if (!f) { *err = sl_cstr(strerror(errno)); return false; }
    i64 n = 0;
    uint8_t *p = ds_top;
    for (;;) {
        sl_reserve(n + 65536);
        size_t k = fread(p + n, 1, 65536, f);
        n += k;
        if (k < 65536) break;
    }
    fclose(f);
    ds_top = p + n;
    *out = (sl_str){p, n};
    return true;
}
static bool sl_write_file(sl_str path, sl_str s) {
    uint8_t *mark = ds_top;
    FILE *f = fopen(sl_to_c(path), "wb");
    ds_top = mark;
    if (!f) return false;
    bool ok = fwrite(s.p, 1, s.len, f) == (size_t)s.len;
    return fclose(f) == 0 && ok;
}
static bool sl_input(sl_str *out) {
    i64 n = 0;
    uint8_t *p = ds_top;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') { sl_reserve(n + 1); p[n++] = ch; }
    if (ch == EOF && n == 0) return false;
    if (n && p[n - 1] == '\r') n--;
    ds_top = p + n;
    *out = (sl_str){p, n};
    return true;
}
static void sl_exit(i64 code) { fflush(stdout); exit((int)code); }
